func s2Rec16(x, y rec16) (rec16, rec16) {
	if y.id < x.id {
		return y, x
	}
	return x, y
}

func heapSortRec16(a []rec16) {
	n := len(a)
	if n < 2 {
		return
	}
	for i := n / 2; ; {
		var k rec16
		if i > 0 {
			i--
			k = a[i]
		} else {
			n--
			if n == 0 {
				return
			}
			k = a[n]
			a[n] = a[0]
		}
		j := i
		for j*2+1 < n {
			child := j*2 + 1
			if child+1 < n && (a[child].id < a[child+1].id) {
				child++
			}
			if !(k.id < a[child].id) {
				break
			}
			a[j] = a[child]
			j = child
		}
		a[j] = k
	}
}

