	i := 1
	for i < n && !(data[i].id < data[i-1].id) {
		i++
	}
	runs, ascEnd = 1, i
	for i < n {
		if runs++; runs > k {
			break
		}
		if runs%2 == 0 {
			for i < n && !(data[i-1].id < data[i].id) {
				i++
			}
		} else {
			for i < n && !(data[i].id < data[i-1].id) {
				i++
			}
		}
	}
	return runs, ascEnd
